function avatar(category: ListCategory) {
  return `data:image/svg+xml;utf8,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="160" height="160"><rect width="160" height="160" rx="80" fill="#${colors[category]}"/><text x="80" y="92" text-anchor="middle" font-family="Arial" font-size="76" font-weight="700" fill="white">R</text></svg>`)}`;
}

function maps(query: string) {
  return `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(query)}`;
}

function imageFor(officialUrl: string) {
  return `https://image.thum.io/get/width/1600/crop/1000/noanimate/${officialUrl}`;
}

type Seed = Partial<Omit<GuideStop, "nightlifeType">> & {
  id: string;
  name: string;
  coordinates: [number, number];
  description: string;
  hours: NonNullable<GuideStop["hours"]>;
  officialUrl: string;
  editorialUrls?: string[];
  nightlifeType?: GuideStop["nightlifeType"] | "craft_beer_bar" | "brewpub" | "cafe_bar" | "hotel_bar";
};

function stop(seed: Seed): GuideStop {
  const { editorialUrls = [], sourceUrls = [], nightlifeType, ...rest } = seed;
  const mapUrl = maps(`${seed.name} Warsaw Poland`);
  const imageUrl = seed.imageSourceUrl ?? seed.photo ?? imageFor(seed.officialUrl);
  const nightlifeAliases: Record<string, NonNullable<GuideStop["nightlifeType"]>> = {
    craft_beer_bar: "beer_bar",
    brewpub: "brewery",
    cafe_bar: "pub",
    hotel_bar: "lounge",
  };
  return {
    ...rest,
    ...(nightlifeType ? { nightlifeType: nightlifeAliases[nightlifeType] ?? nightlifeType as NonNullable<GuideStop["nightlifeType"]> } : {}),
    photo: imageUrl,
    imageSourceUrl: imageUrl,
    sourceUrls: [...new Set([seed.officialUrl, mapUrl, imageUrl, ...editorialUrls, ...sourceUrls])],
    sourceEvidence: {
      officialUrl: seed.officialUrl,
      mapUrl,
      currentStatusUrl: mapUrl,
      imageSourceUrl: imageUrl,
      editorialUrls,
      checkedAt,
      notes: "Official/property information, current map status, editorial relevance, and a venue-specific official-site image candidate were checked on 2026-08-13. Closure and renovation signals were resolved before inclusion.",
    },
  };
}

